contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 loanID, address to) public {
        require(to != address(0));
        require(to != address(this));

        // fresh contract: no loans exist, so lender is zero and msg.sender is this contract
        bool reverted;
        try c.approveTransfer(to, loanID) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted == true &&
            c.approvals(loanID) == address(0) &&
            c.getLoan(loanID).lender == address(0) &&
            c.getLoan(loanID).lender != to &&
            c.getLoan(loanID).lender != address(this)
        );
    }

    receive() external payable {}
}

