contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 rate, uint256 d1, uint256 d2) public {
        require(d1 <= d2);
        require(d2 <= 3650 days);
        require(amount <= 1e30);
        require(rate <= 1e24);
        require(amount > 0 && rate > 0);

        uint256 i1 = c.interestFor(amount, rate, d1);
        uint256 i2 = c.interestFor(amount, rate, d2);
        uint256 j1 = c.interestFor(amount * 2, rate, d1);

        assert(i1 <= i2 && i1 <= j1);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 rate, uint256 duration) public payable {
        // Bounds so that no overflow can occur and the rounding lemma is exact.
        require(amount <= 1e30);
        require(rate <= 1e9);
        require(duration <= 365 days);

        uint256 i1 = c.interestFor(amount, rate, duration);
        uint256 i2 = c.interestFor(amount * 2, rate, duration);

        // Homogeneity up to one unit of rounding: doubling the principal
        // doubles the interest, losing at most 1 wei to integer division.
        assert(2 * i1 <= i2 && i2 <= 2 * i1 + 1);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 rate, uint256 duration) public payable {
        require(amount <= 1e30);
        require(rate <= 1e18);
        require(duration <= 365 days);

        uint256 interest = c.interestFor(amount, rate, duration);

        // rate * duration <= 1e18 * 365 days, so the yearly fractional rate
        // is at most 100% of the principal: interest can never exceed amount.
        assert(interest <= amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 duration) public payable {
        require(amount <= 1e24);
        require(duration <= 365 days);

        uint256 interest = c.interestFor(amount, 1e18, duration);

        // With DECIMALS_INTEREST = 1e18 and rate = 1e18,
        // interest = (amount * (1e18 * duration / 365 days)) / 1e18
        //          = amount * duration / 365 days (integer division).
        assert(interest == (amount * duration) / 365 days);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 rate, uint256 d1, uint256 d2) public payable {
        require(amount <= 1e18);
        require(rate <= 1e24);
        require(d1 <= 365 days);
        require(d2 >= d1);
        require(d2 <= 365 days);

        uint256 i1 = c.interestFor(amount, rate, d1);
        uint256 i2 = c.interestFor(amount, rate, d2);

        assert(i1 <= i2);
    }

    receive() external payable {}
}
